// 确定性 GPT 风格子词近似分词（小写 + 4 字符分块 + 标点/空白独立成 token）
function tokenize(text){
  if(text==null) return [];
  var raw=String(text);
  var parts=raw.split(/(\s+)/);
  var toks=[];
  var PUNCT=/^[.,!?;:'"()\[\]{}<>\/\\@#$%^&*\-_=+~`|]$/;
  for(var i=0;i<parts.length;i++){
    var p=parts[i];
    if(p==='') continue;
    if(/^\s+$/.test(p)){ toks.push(p); continue; }
    var sub=p.split(/([.,!?;:'"()\[\]{}<>\/\\@#$%^&*\-_=+~`|])/).filter(function(x){return x.length;});
    for(var j=0;j<sub.length;j++){
      var s=sub[j];
      if(s.length===0) continue;
      if(PUNCT.test(s)){ toks.push(s); }
      else {
        var lower=s.toLowerCase(), k=0;
        while(k<lower.length){ toks.push(lower.slice(k,k+4)); k+=4; }
      }
    }
  }
  return toks;
}
function countTokens(text){ return tokenize(text).length; }
var PRICING={
  'gpt-4o-mini':{in:0.15,out:0.60},
  'gpt-4o':{in:2.5,out:10},
  'claude-3.5-sonnet':{in:3,out:15},
  'deepseek-chat':{in:0.27,out:1.1},
  'gemini-1.5-pro':{in:1.25,out:5}
};
function estimateCost(text, model){
  var t=countTokens(text);
  var p=PRICING[model]; if(!p) throw new Error('UNKNOWN_MODEL');
  return { tokens:t, inputCost:t*p.in/1e6, outputCost:t*p.out/1e6 };
}
function breakdown(text){
  var t=String(text||'');
  var words=(t.trim().match(/\S+/g)||[]).length;
  return { chars:t.length, words:words, estTokens:countTokens(t) };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tokenize:tokenize, countTokens:countTokens, estimateCost:estimateCost, breakdown:breakdown, PRICING:PRICING };
}
if (typeof window !== 'undefined') {
  window.TokenForgePure = { tokenize:tokenize, countTokens:countTokens, estimateCost:estimateCost, breakdown:breakdown, PRICING:PRICING };
}
